/**
 * Bài 36 — 文化の違い (Khác biệt văn hoá) · TIẾP SAU SÁCH, cấp N3 (xem ../SOAN-BAI.md mục 8). Bài đầu của chặng 36–40
 * (Bài 40 = ôn tập & thi thử N3).
 * Người học đã xong Bài 1–15 (ポイント 1–124 — trong đó ～たり～たり (ポイント 99), N や N など (Bài 4), ～ても (Bài 17)),
 * Bài 16–24, Bài 25 (ôn N4), Bài 26–29, Bài 30 (～って — kể cả "N って = N というのは" chỉ NHẬN RA, ～とのことだ,
 * ～ということだ (1) nghe nói (2) tức là — ということは đầu câu, ～とか "nghe đâu", にとって, として — N としても "với tư
 * cách N cũng"), Bài 31 (～に違いない, ～はずがない, ～わけだ・わけではない), Bài 32 (～ものだ, ～ことだ, ～につれて, ～一方だ —
 * それにしても gặp như một từ), Bài 33 (～によると, ～に基づいて, ～をもとに, ～とともに), Bài 34 (～がちだ, ～気味, ～っぱなし,
 * ～としたら) và Bài 35 (～させられる, ～させていただく, ～ばよかった). KHÔNG dạy lại — chỉ dùng lại trong câu (ghi "ôn: Bài X").
 *
 * Ngữ pháp (N3) — nhóm "GIẢI THÍCH – LIỆT KÊ – NHƯỢNG BỘ": ① N というのは ～ことだ／～という意味だ (định nghĩa, giải thích
 * một từ / khái niệm — văn nói lịch sự) + というのは đầu câu = "sở dĩ… là vì" (～。というのは、～からだ) · ② N とは ～ことだ
 * (định nghĩa — văn viết, tiêu đề, từ điển, thuyết trình) + 普通形 ＋ とは "không ngờ…!" (ngạc nhiên; ～とは思わなかった) ·
 * ③ 「X」は「Y」という意味だ (X nghĩa là Y; どういう意味ですか · そういう意味ではない · ～という意味で) · ④ 普通形 ＋ ということは
 * ～ということだ (việc… có nghĩa là… — ôn Bài 30 ④, mở rộng sang ý nghĩa / bản chất) + ～ということはない "không có chuyện…" ·
 * ⑤ ～とか～とか (liệt kê ví dụ, văn nói: N / V普通形 / A) · ⑥ ～やら～やら "nào là… nào là…" (nhiều thứ lộn xộn, cảm xúc
 * lẫn lộn: うれしいやら恥ずかしいやら) · ⑦ ～にしても "dù là… thì cũng" (+ 疑問詞にしても, いずれにしても) và ～にしても～
 * にしても "dù A hay B" · ⑧ BẢNG PHÂN BIỆT というのは ↔ とは ↔ って (Bài 30) · ⑨ BẢNG PHÂN BIỆT とか～とか ↔ や～など
 * (Bài 4) ↔ やら～やら ↔ たり～たり (ポイント 99) · ⑩ BẢNG PHÂN BIỆT にしても ↔ ても (Bài 17) ↔ としても (giả định) + chỉ cần
 * NHẬN RA: ～にしろ／～にせよ (N2), ～というと／～といえば (N3), 何やら.
 * Từ vựng: 66 từ (N3 là chính, từ N2 có ghi cấp): văn hoá & so sánh, phép lịch sự & giao tiếp, ăn uống & nơi công cộng,
 * lễ tết & tặng quà, giải thích khái niệm & thuyết trình — kèm bảng TỪ DỄ NHẦM (類義語) và KẾT HỢP TỪ (コロケーション).
 * Từ đã học ở Bài 1–35 (文化, 伝統, 習慣, 価値観, 常識, 当たり前 — Bài 32/31; 比較する, 一般的, 年上・年下, 逆に — Bài 28;
 * 特徴, 誤解 — Bài 31; あいさつする, 燃えるごみ, 包む — Bài 18; 遠慮する, 敬語 — Bài 16/24; 分別する, 民族 — Bài 26/27;
 * 習慣, 慣れる — Bài 11/14; 意外 — Bài 33; 並ぶ, 失礼, 尊敬, 驚く, 違う…) KHÔNG lặp lại — gặp trong câu là ôn.
 * Chữ Hán mới (21): 異 較 祝 贈 包 列 譲 握 距 離 旧 般 徴 周 囲 宗 儀 恥 燃 省 略 (N3 là chính theo các bảng tham khảo phổ
 * biến; 較・贈・譲・旧・般・宗・恥・略 có bảng xếp N2, 握・距・徴・儀 N2 — JLPT không công bố danh sách chữ chính thức) — không trùng
 * hanTu.ts, hanTu16–34.ts, hanLop.ts, bảng chữ Hán Bài 1–34 (則・姿 đã thuộc Bài 34 — chỉ dùng lại trong từ {規則|きそく}・{姿勢|しせい}). Thẻ chữ Hán: hanTu36.ts (HAN_TU_36).
 * Hội thoại, câu ví dụ, bài đọc, kịch bản nghe: VIẾT MỚI 100%, không chép giáo trình/đề thi nào.
 *
 * Nhân vật (giới tính quyết định giọng đọc, theo sách p.14): nữ = パク, ワン, アンナ, メアリー, マリヤム, 山口, 木村, リン, 鈴木,
 * {佐藤先生|さとうせんせい} · nam = マルコ, ダニエル, ナタポン, カルロス, 西川, 本田先生, {小林店長|こばやしてんちょう}.
 * Nối tiếp: リン (nữ, người Việt, năm nhất khoa Kinh tế trường {みなと大学|みなとだいがく}), カルロス (nam, cùng ゼミ của cô 佐藤),
 * ナタポン (nam, cao học, làm thêm ở ひまわり食堂 của anh 小林), ダニエル (nam, {国際寮|こくさいりょう}), ワン (nữ, thực tập ở công ty
 * phần mềm さくらシステム — Bài 24/30), 鈴木 (nữ, nhân viên さくらシステム, kèm ワン), {森課長|もりかちょう} (nam — Bài 24/30).
 * Hội thoại: role 'a'/'c' = giọng nữ, 'b'/'examiner' = giọng nam (trang tự đổi sang giọng thứ hai khi có hai người cùng giới).
 * Nghe: 'ja-nu' = nữ, 'ja-nam' = nam. Người MỚI (chỉ ở phần nghe / đọc): {留学生|りゅうがくせい}センターの{職員|しょくいん} (nữ),
 * ラジオの{司会者|しかいしゃ} (nam), {文化人類学|ぶんかじんるいがく}の{先生|せんせい} (nam — bài giảng), {高橋|たかはし} (nữ — người viết blog).
 * Hình: tên trong scripts/hinh/fluent-catalog.json (Fluent Emoji).
 */
import type { Block, Ex, Lesson } from '@/components/sach-hoc/types';

const E = (en: string, ro: string, vi: string): Ex => ({ en, ro, vi });

/**
 * Đáp án gõ tay: viết một lần bằng {漢字|かな}, hàm sinh đủ cách viết chữ Hán / kana
 * (máy chấm đã tự bỏ dấu câu, dấu cách và đổi chữ số toàn khổ). Phần tử đầu = dạng
 * toàn chữ Hán, là đáp án hiển thị.
 */
const V = (...xs: string[]): string[] => {
  const out = new Set<string>();
  for (const x of xs) {
    const slots = x
      .split(/(\{[^|}]+\|[^}]+\})/)
      .filter(Boolean)
      .map((p) => {
        const m = /^\{([^|}]+)\|([^}]+)\}$/.exec(p);
        return m ? [m[1], m[2]] : [p];
      });
    const n = slots.filter((s) => s.length > 1).length;
    if (n <= 8) {
      let acc = [''];
      for (const s of slots) acc = acc.flatMap((a) => s.map((c) => a + c));
      acc.forEach((a) => out.add(a));
    } else {
      out.add(slots.map((s) => s[0]).join(''));
      out.add(slots.map((s) => s[s.length - 1]).join(''));
      slots.forEach((s, i) => {
        if (s.length > 1) out.add(slots.map((t, j) => (j === i ? t[1] : t[0])).join(''));
      });
    }
  }
  return [...out];
};

type Line = [who: string, role: 'a' | 'b' | 'c' | 'examiner' | 'candidate', text: string, ro: string, vi: string];
const DL = (title: string, lines: Line[]): Block => ({
  t: 'dialogue',
  title,
  lines: lines.map(([who, role, text, ro, vi]) => ({ who, role, text, ro, vi })),
});

